#include <stdio.h>
int main()
{
int ary[4];
int sum = 0;
int i;
for (i = 0; i < 4; i++) {
printf("%d번 째 값을 입력하시오 : ", i + 1);
scanf("%d", &ary[i]);
}
for (i = 3; i > 0; i--)
sum += ary[i];
printf("%d \n", sum);
return 0;
}

#include <stdio.h>
int star = 10;
void printStar() {
printf("%d \n", star);
}
int main()
{
int star = 5;
printStar();
printf("%d \n", star);
return 0;
}
